public class Main {
    static int parseOneOrTwoDigits(String text) {
        if (text.length() < 1 || text.length() > 2) {
            return -1;
        }
        int value = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c < '0' || c > '9') {
                return -1;
            }
            value = value * 10 + (c - '0');
        }
        return value;
    }
    public static void main(String[] args) {
        System.out.println(parseOneOrTwoDigits("07"));
    }
}

